<?php
declare(strict_types=1);
$root=__DIR__;
require_once $root.'/app/FontManager.php';
require_once $root.'/app/Database.php';
$appVersion=trim((string)@file_get_contents($root.'/VERSION'))?:'2.0.0';
if(is_file($root.'/config/config.php')){header('Location: index.php');exit;}
ini_set('display_errors','0');ini_set('log_errors','1');date_default_timezone_set('Asia/Tehran');
session_name('sokna_install_v2');if(session_status()!==PHP_SESSION_ACTIVE)session_start();
if(empty($_SESSION['install_csrf']))$_SESSION['install_csrf']=bin2hex(random_bytes(32));
$errors=[];$done=false;$installedUser='';
function h(mixed $v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function detected_install_url_v2(): string{
    $https=(!empty($_SERVER['HTTPS'])&&strtolower((string)$_SERVER['HTTPS'])!=='off');$scheme=$https?'https':'http';$host=(string)($_SERVER['HTTP_HOST']??'localhost');$dir=rtrim(dirname(str_replace('\\','/',(string)($_SERVER['SCRIPT_NAME']??'/install.php'))),'/.');return $scheme.'://'.$host.($dir!==''?$dir:'');
}
function schema_statements(string $sql): array{return array_values(array_filter(array_map('trim',preg_split('/;\s*(?:\r?\n|$)/',$sql)?:[])));}
function schema_table_suffixes(string $schema): array{preg_match_all('/CREATE\s+TABLE\s+IF\s+NOT\s+EXISTS\s+`\{\{prefix\}\}([a-z0-9_]+)`/i',$schema,$m);return array_values(array_unique($m[1]??[]));}
function drop_created_tables(PDO $pdo,string $prefix,array $suffixes): void{
    try{$pdo->exec('SET FOREIGN_KEY_CHECKS=0');foreach(array_reverse($suffixes) as $suffix){$name=$prefix.$suffix;if(preg_match('/^[A-Za-z0-9_]+$/',$name))$pdo->exec('DROP TABLE IF EXISTS `'.$name.'`');}$pdo->exec('SET FOREIGN_KEY_CHECKS=1');}catch(Throwable $e){try{$pdo->exec('SET FOREIGN_KEY_CHECKS=1');}catch(Throwable $ignored){}}
}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals((string)($_SESSION['install_csrf']??''),(string)($_POST['csrf']??'')))$errors[]='درخواست نصب معتبر نیست؛ صفحه را تازه کنید.';
    $dbHost=trim((string)($_POST['db_host']??'localhost'));$dbPort=max(1,min(65535,(int)($_POST['db_port']??3306)));$dbName=trim((string)($_POST['db_name']??''));$dbUser=trim((string)($_POST['db_user']??''));$dbPass=(string)($_POST['db_pass']??'');$prefix=preg_replace('/[^A-Za-z0-9_]/','',(string)($_POST['db_prefix']??'sokna_'))??'';
    $siteUrl=rtrim(trim((string)($_POST['site_url']??detected_install_url_v2())),'/');$property=trim((string)($_POST['property_name']??'سکنا'));$username=trim((string)($_POST['admin_user']??'admin'));$display=trim((string)($_POST['admin_name']??'مدیر سکنا'));$password=(string)($_POST['admin_pass']??'');
    foreach(['pdo_mysql','json','mbstring','zip'] as $ext)if(!extension_loaded($ext))$errors[]='افزونه PHP «'.$ext.'» روی هاست فعال نیست.';
    if($dbName===''||$dbUser==='')$errors[]='نام پایگاه داده و کاربر آن الزامی است.';
    if(!preg_match('~^https?://[^\s]+$~i',$siteUrl))$errors[]='نشانی سامانه باید با http یا https شروع شود.';
    if($prefix===''||strlen($prefix)>32)$errors[]='پیشوند جدول‌ها باید بین ۱ تا ۳۲ نویسه باشد.';
    if($property===''||(function_exists('mb_strlen')?mb_strlen($property,'UTF-8'):strlen($property))>120)$errors[]='نام مجموعه معتبر نیست.';
    if(!preg_match('/^[A-Za-z0-9_.-]{3,80}$/',$username))$errors[]='نام کاربری مدیر باید ۳ تا ۸۰ نویسه و شامل حروف انگلیسی، عدد، نقطه، خط تیره یا زیرخط باشد.';
    if(strlen($password)<10)$errors[]='رمز مدیر باید حداقل ۱۰ نویسه باشد.';
    foreach(['config','storage','storage/logs','storage/backups','uploads'] as $dir){$path=$root.'/'.$dir;if(!is_dir($path)&&!@mkdir($path,0750,true))$errors[]='پوشه «'.$dir.'» ساخته نشد.';elseif(!is_writable($path))$errors[]='پوشه «'.$dir.'» برای PHP قابل نوشتن نیست.';}
    if(!$errors){$pdo=null;$suffixes=[];$created=false;try{
        $pdo=new PDO("mysql:host={$dbHost};port={$dbPort};dbname={$dbName};charset=utf8mb4",$dbUser,$dbPass,Database::pdoOptions());Database::synchronizeSessionTimezone($pdo,'Asia/Tehran');
        $schemaRaw=(string)file_get_contents($root.'/database/schema.sql');$suffixes=schema_table_suffixes($schemaRaw);if(!$suffixes)throw new RuntimeException('فهرست جدول‌های نسخه ۲ از فایل ساختار استخراج نشد.');
        $check=$pdo->prepare('SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=? AND LEFT(TABLE_NAME,?)=? LIMIT 1');$check->execute([$dbName,strlen($prefix),$prefix]);if($existing=$check->fetchColumn())throw new RuntimeException('با این پیشوند از قبل جدول وجود دارد ('.$existing.'). برای نصب تمیز، پایگاه داده/پیشوند خالی انتخاب کنید.');
        $schema=str_replace('{{prefix}}',$prefix,$schemaRaw);$created=true;foreach(schema_statements($schema) as $sql)$pdo->exec($sql);
        $pdo->beginTransaction();$defaults=require $root.'/data/defaults.php';
        $user=$pdo->prepare("INSERT INTO `{$prefix}users` (username,password_hash,display_name,role,active) VALUES (?,?,?,?,1)");$user->execute([$username,password_hash($password,PASSWORD_DEFAULT),$display,'admin']);$adminId=(int)$pdo->lastInsertId();
        $settings=(array)($defaults['settings']??[]);$settings['site_url']=$siteUrl;$settings['property_name']=$property;$settings['public_token']=bin2hex(random_bytes(24));$st=$pdo->prepare("INSERT INTO `{$prefix}settings` (`key`,`value`) VALUES (?,?)");foreach($settings as $k=>$v)$st->execute([(string)$k,is_string($v)?$v:json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
        $feature=$pdo->prepare("INSERT INTO `{$prefix}features` (feature_key,enabled) VALUES (?,?)");foreach((array)($defaults['features']??[]) as $k=>$v)$feature->execute([(string)$k,(int)(bool)$v]);
        $room=$pdo->prepare("INSERT INTO `{$prefix}rooms` (name,slug,standard_capacity,max_capacity,base_rate,extra_person_rate,active,sort_order) VALUES (?,?,?,?,?,?,1,?)");foreach((array)($defaults['rooms']??[]) as $i=>$r)$room->execute([(string)$r['name'],(string)$r['slug'],(int)$r['standard'],(int)$r['max'],(int)$r['base_rate'],(int)$r['extra_rate'],$i+1]);
        $tpl=$pdo->prepare("INSERT INTO `{$prefix}message_templates` (template_key,title,body,active) VALUES (?,?,?,?)");foreach((array)($defaults['templates']??[]) as $t)$tpl->execute([$t[0],$t[1],$t[2],(int)$t[3]]);
        $schemaChecksum=hash_file('sha256',$root.'/database/schema.sql');$mig=$pdo->prepare("INSERT INTO `{$prefix}schema_migrations` (version,checksum,operation_id,status) VALUES ('2.6.0-rc7-qa1',?,'clean-install','success')");$mig->execute([$schemaChecksum]);
        $pdo->commit();
        $config=['db'=>['host'=>$dbHost,'port'=>$dbPort,'name'=>$dbName,'user'=>$dbUser,'pass'=>$dbPass,'prefix'=>$prefix],'timezone'=>'Asia/Tehran','session_name'=>'sokna_session','app_key'=>bin2hex(random_bytes(32)),'cafe_api'=>['token_hash'=>'','allow_http_localhost'=>true,'trust_proxy_https'=>false,'trusted_proxy_ips'=>[]]];
        $body="<?php\ndeclare(strict_types=1);\nreturn ".var_export($config,true).";\n";$tmp=$root.'/config/config.php.'.bin2hex(random_bytes(4)).'.tmp';if(file_put_contents($tmp,$body,LOCK_EX)===false)throw new RuntimeException('نوشتن موقت تنظیمات ناموفق بود.');@chmod($tmp,0640);if(!@rename($tmp,$root.'/config/config.php')){@unlink($tmp);throw new RuntimeException('فعال‌کردن فایل تنظیمات ناموفق بود.');}@chmod($root.'/config/config.php',0640);
        @file_put_contents($root.'/storage/installed.lock',$appVersion.' '.date(DATE_ATOM)."\n",LOCK_EX);try{FontManager::ensureLocal(2);}catch(Throwable $ignored){}unset($_SESSION['install_csrf']);$done=true;$installedUser=$username;
    }catch(Throwable $e){if($pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();if($created&&$pdo instanceof PDO)drop_created_tables($pdo,$prefix,$suffixes);@unlink($root.'/config/config.php');$logDir=$root.'/storage/logs';if(!is_dir($logDir))@mkdir($logDir,0750,true);@file_put_contents($logDir.'/install.log','['.date(DATE_ATOM).'] '.get_class($e).': '.$e->getMessage()."\n",FILE_APPEND|LOCK_EX);$errors[]=$e instanceof RuntimeException?$e->getMessage():'نصب کامل نشد. اطلاعات پایگاه داده و مجوز پوشه‌ها را بررسی کنید.';}}
}
?><!doctype html><html lang="fa-IR" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#846554"><meta name="color-scheme" content="light"><script>document.documentElement.dataset.theme='light';</script><style id="soknaCriticalPaint">html,body{min-height:100%;margin:0;background:#f6f1ed;color-scheme:light}html[data-theme="dark"],html[data-theme="dark"] body{background:#191817;color-scheme:dark}html[data-public-page="1"],html[data-public-page="1"] body{background:#f7f3ed;color-scheme:light}</style><title>نصب سکنا ۲</title><link rel="icon" href="assets/icons/favicon-32.png"><link rel="apple-touch-icon" href="assets/icons/apple-touch-icon.png"><link rel="stylesheet" href="assets/app.css?v=<?=h(rawurlencode($appVersion))?>"></head><body class="login-page"><main class="login-shell install-wide"><section class="login-card"><header class="login-copy"><span class="brand-mark large brand-logo"><img src="assets/icons/icon-192.png" alt="" aria-hidden="true"></span><span class="eyebrow">نسخه <?=h($appVersion)?></span><h1>نصب تمیز سامانه سکنا</h1><p>ساختار نسخه ۲ روی یک پیشوند خالی ساخته می‌شود و هیچ داده نسخه قدیمی وارد این نصب نمی‌شود.</p></header>
<?php foreach($errors as $er):?><div class="flash error"><?=h($er)?></div><?php endforeach;?>
<?php if($done):?><div class="panel"><h2>نصب با موفقیت کامل شد</h2><p>اتاق‌ها، تنظیمات پایه و حساب مدیر ساخته شدند. نام کاربری مدیر: <bdi class="technical" dir="ltr"><?=h($installedUser)?></bdi></p><a class="btn primary full" href="index.php?page=login">ورود به سامانه</a></div>
<?php else:?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h($_SESSION['install_csrf'])?>"><div class="form-grid"><label class="field full"><span>نشانی سامانه</span><input dir="ltr" name="site_url" value="<?=h($_POST['site_url']??detected_install_url_v2())?>" required></label><label class="field full"><span>نام مجموعه</span><input name="property_name" value="<?=h($_POST['property_name']??'سکنا')?>" required></label><label class="field"><span>میزبان پایگاه داده</span><input dir="ltr" name="db_host" value="<?=h($_POST['db_host']??'localhost')?>" required></label><label class="field"><span>درگاه</span><input dir="ltr" name="db_port" value="<?=h($_POST['db_port']??'3306')?>" required></label><label class="field"><span>نام پایگاه داده</span><input dir="ltr" name="db_name" value="<?=h($_POST['db_name']??'')?>" required></label><label class="field"><span>کاربر پایگاه داده</span><input dir="ltr" name="db_user" value="<?=h($_POST['db_user']??'')?>" required></label><label class="field"><span>رمز پایگاه داده</span><input dir="ltr" type="password" name="db_pass"></label><label class="field"><span>پیشوند جدول‌ها</span><input dir="ltr" name="db_prefix" value="<?=h($_POST['db_prefix']??'sokna_')?>" required></label><label class="field"><span>نام نمایشی مدیر</span><input name="admin_name" value="<?=h($_POST['admin_name']??'مدیر سکنا')?>" required></label><label class="field"><span>نام کاربری مدیر</span><input dir="ltr" name="admin_user" value="<?=h($_POST['admin_user']??'admin')?>" required></label><label class="field full"><span>رمز مدیر</span><input type="password" name="admin_pass" minlength="10" autocomplete="new-password" required><small>حداقل ۱۰ نویسه</small></label></div><button class="btn primary full" type="submit">ساخت نسخه ۲</button></form><?php endif;?>
</section></main></body></html>
